import type {
  ConsentRecord,
  CvExtraction,
  ExtractionStatus,
  Outcome,
  PrivacyNotice,
} from '@tt/domain';
import { sql } from 'drizzle-orm';
import { boolean, customType, index, integer, jsonb, pgTable, text, timestamp, uniqueIndex } from 'drizzle-orm/pg-core';
import { organization } from './auth.js';
import { job } from './job.js';

/** Postgres full-text vector: only ever generated by the database, never written by the application. */
const tsvector = customType<{ data: string }>({ dataType: () => 'tsvector' });

const organizationRef = () =>
  text('organization_id')
    .notNull()
    .references(() => organization.id, { onDelete: 'restrict' });

/**
 * Versioned privacy notice (PLAN §7). Rows are never updated: a change is a new version, and every application
 * keeps the version it consented to. `version` is unique inside the organization.
 */
export const privacyNotice = pgTable(
  'privacy_notice',
  {
    id: text('id').primaryKey(),
    organizationId: organizationRef(),
    version: integer('version').notNull(),
    language: text('language').$type<PrivacyNotice['language']>().notNull(),
    text: text('text').notNull(),
    contactEmail: text('contact_email').notNull(),
    retentionDays: jsonb('retention_days').$type<PrivacyNotice['retentionDays']>().notNull(),
    createdBy: text('created_by').notNull(),
    createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
  },
  (table) => [uniqueIndex('privacy_notice_org_version_uidx').on(table.organizationId, table.version)],
);

/** One person per organization: the email is unique case-insensitively. */
export const candidate = pgTable(
  'candidate',
  {
    id: text('id').primaryKey(),
    organizationId: organizationRef(),
    firstName: text('first_name').notNull(),
    lastName: text('last_name').notNull(),
    email: text('email').notNull(),
    phone: text('phone'),
    linkedinUrl: text('linkedin_url'),
    tags: text('tags').array().notNull().default(sql`'{}'::text[]`),
    talentPool: boolean('talent_pool').notNull().default(false),
    retentionExpiresAt: timestamp('retention_expires_at', { withTimezone: true }).notNull(),
    createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
    updatedAt: timestamp('updated_at', { withTimezone: true }).defaultNow().notNull(),
  },
  (table) => [
    uniqueIndex('candidate_org_email_uidx').on(table.organizationId, sql`lower(${table.email})`),
    index('candidate_org_created_at_idx').on(table.organizationId, sql`${table.createdAt} desc`),
  ],
);

export const application = pgTable(
  'application',
  {
    id: text('id').primaryKey(),
    organizationId: organizationRef(),
    jobId: text('job_id')
      .notNull()
      .references(() => job.id, { onDelete: 'restrict' }),
    candidateId: text('candidate_id')
      .notNull()
      .references(() => candidate.id, { onDelete: 'restrict' }),
    stageId: text('stage_id').notNull(),
    outcome: text('outcome').$type<Outcome>(),
    message: text('message').notNull().default(''),
    cvKey: text('cv_key').notNull(),
    cvFileName: text('cv_file_name').notNull(),
    cvMediaType: text('cv_media_type').notNull(),
    cvSizeBytes: integer('cv_size_bytes').notNull(),
    consent: jsonb('consent').$type<ConsentRecord>().notNull(),
    retentionExpiresAt: timestamp('retention_expires_at', { withTimezone: true }).notNull(),
    source: text('source').$type<'careers_page' | 'manual'>().notNull(),
    createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
    updatedAt: timestamp('updated_at', { withTimezone: true }).defaultNow().notNull(),
    stageChangedAt: timestamp('stage_changed_at', { withTimezone: true }).defaultNow().notNull(),
    closedAt: timestamp('closed_at', { withTimezone: true }),
    /** Deadline of the promise to answer; null once answered or decided. */
    responseDueAt: timestamp('response_due_at', { withTimezone: true }),
    respondedAt: timestamp('responded_at', { withTimezone: true }),
  },
  (table) => [
    // A candidate cannot have two OPEN applications to the same job; a decided one does not block a new one.
    uniqueIndex('application_job_candidate_open_uidx')
      .on(table.jobId, table.candidateId)
      .where(sql`${table.outcome} is null`),
    index('application_org_job_idx').on(table.organizationId, table.jobId),
    index('application_org_candidate_idx').on(table.organizationId, table.candidateId),
    // Backs the deadline scan and the attention list: only open applications still waiting for an answer.
    index('application_awaiting_response_idx')
      .on(table.organizationId, table.responseDueAt)
      .where(sql`${table.outcome} is null and ${table.responseDueAt} is not null`),
  ],
);

export const candidateNote = pgTable(
  'candidate_note',
  {
    id: text('id').primaryKey(),
    organizationId: organizationRef(),
    candidateId: text('candidate_id')
      .notNull()
      .references(() => candidate.id, { onDelete: 'restrict' }),
    applicationId: text('application_id').references(() => application.id, { onDelete: 'restrict' }),
    /** Plain text with no foreign key: notes survive the removal of the user who wrote them. */
    authorId: text('author_id').notNull(),
    body: text('body').notNull(),
    createdAt: timestamp('created_at', { withTimezone: true }).defaultNow().notNull(),
  },
  (table) => [index('candidate_note_org_candidate_idx').on(table.organizationId, table.candidateId)],
);

/** `search` is generated by Postgres from `text` and backs full-text search over CVs. */
export const cvExtraction = pgTable(
  'cv_extraction',
  {
    applicationId: text('application_id')
      .primaryKey()
      .references(() => application.id, { onDelete: 'cascade' }),
    organizationId: organizationRef(),
    status: text('status').$type<ExtractionStatus>().notNull(),
    text: text('text'),
    data: jsonb('data').$type<CvExtraction>(),
    source: text('source').$type<'model' | 'text'>(),
    updatedAt: timestamp('updated_at', { withTimezone: true }).defaultNow().notNull(),
    search: tsvector('search').generatedAlwaysAs(sql`to_tsvector('simple', coalesce(text, ''))`),
  },
  (table) => [
    index('cv_extraction_search_idx').using('gin', table.search),
    index('cv_extraction_org_idx').on(table.organizationId),
  ],
);

export type PrivacyNoticeRow = typeof privacyNotice.$inferSelect;
export type CandidateRow = typeof candidate.$inferSelect;
export type ApplicationRow = typeof application.$inferSelect;
export type CandidateNoteRow = typeof candidateNote.$inferSelect;
export type CvExtractionRow = typeof cvExtraction.$inferSelect;
